import Photo from "./subReLearn";
import { Word } from "./subReLearn";
import "./ReLearn.css"
export default function () {
  return (
    <>
      <Photo />
      <h1 className="wow">Gun Devil</h1>
      <Card>
      <Employee
      obj={{
        source:"https://i.pinimg.com/736x/ba/cd/62/bacd6202f4f98eef8bee7b8d0ff6787c.jpg",
        huh:200
    }}
      />
      </Card>
    </>
  );
}

function Employee({obj}) {
  return <img
  src={obj.source}
  width={obj.huh}
  
  />
} 

function Card({children}) {
  return <div
  className="div"
  >{children}</div>
}
